INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000015',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about health and illness in Hindi at A1","Use मुझे बुखार है for symptoms","Visit a doctor or pharmacy"],"explanation":{"intro":"Health vocabulary covers common symptoms, doctor visits and pharmacy interactions in Hindi at A1.","culturalNote":"स्वास्थ्य और बीमारी — Health and Illness: स्वास्थ्य (swasthya) = health (Sanskrit: su = good + stha = standing — being well-placed). बीमारी (bimari) = illness. बुखार (bukhar) = fever. सर्दी-ज़ुकाम (sardi-zukam) = cold and cough. दर्द (dard) = pain. डॉक्टर (doctor) = doctor. दवा (dawa) = medicine. अस्पताल (aspataal) = hospital. दवाखाना (dawakhana) = pharmacy/medicine shop. Key phrase: मुझे बुखार है (Mujhe bukhar hai = I have a fever — dative construction). मुझे X की ज़रूरत है (Mujhe X ki zaroorat hai = I need X). Cultural: India has both allopathic (Western medicine) and traditional systems: आयुर्वेद (Ayurveda), यूनानी (Unani), होमियोपैथी (homeopathy), योग (yoga). AYUSH Ministry (Ayurveda, Yoga, Unani, Siddha, Homeopathy). Turmeric milk (हल्दी दूध = haldi doodh) is a traditional remedy for cold/fever. Doctors are highly respected in Indian society."},"examples":[{"hindi":"मुझे बुखार है और सिर दर्द भी है।","transliteration":"Mujhe bukhar hai aur sir dard bhi hai.","english":"I have a fever and a headache too."},{"hindi":"मुझे दवा की ज़रूरत है।","transliteration":"Mujhe dawa ki zaroorat hai.","english":"I need medicine."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can describe health symptoms in Hindi and ask for medicine."}}',
'{"items":[{"word":"बीमारी","translation":"illness","transliteration":"bimari","pronunciation":"bi-MA-ree","example":"बीमारी होना।"},{"word":"बुखार","translation":"fever","transliteration":"bukhar","pronunciation":"bu-KHAR","example":"बुखार है।"},{"word":"दवा","translation":"medicine","transliteration":"dawa","pronunciation":"da-WA","example":"दवा लेना।"},{"word":"अस्पताल","translation":"hospital","transliteration":"aspataal","pronunciation":"as-pa-TAAL","example":"अस्पताल जाना।"},{"word":"ज़रूरत","translation":"need","transliteration":"zaroorat","pronunciation":"za-ROO-rat","example":"ज़रूरत है।"},{"word":"भी","translation":"also/too","transliteration":"bhi","pronunciation":"bhi","example":"मुझे भी।"}]}',
'{"title":"मुझे X की ज़रूरत है — I need X (ज़रूरत = need, की for feminine)","pattern":"मुझे X की ज़रूरत है = I need X. ज़रूरत (zaroorat) = need (feminine noun — from Persian/Arabic). की = of/''s (feminine possessive — agrees with ज़रूरत which is feminine). मुझे = to me (dative). So literally: to me X''s need is. X takes की before ज़रूरत because ज़रूरत is feminine.","explanation":"ज़रूरत (zaroorat) = need (feminine noun). मुझे X की ज़रूरत है = I need X. की agrees with ज़रूरत (feminine). X की ज़रूरत = the need of X. Possessive: X की Y = Y of X (when Y is feminine). Compare: मुझे X चाहिए (Mujhe X chahiye = I want/need X — more direct want). ज़रूरत = need (more urgent necessity). चाहिए = want/require (general want or need). Contrast: आपको क्या चाहिए? (What do you need? — common in shops). आपको किस की ज़रूरत है? (What is needed by you? — more formal).","examples":[{"sentence":"उसे पानी की ज़रूरत है।","transliteration":"Use paani ki zaroorat hai.","translation":"He/she needs water."},{"sentence":"मुझे मदद की ज़रूरत है।","transliteration":"Mujhe madad ki zaroorat hai.","translation":"I need help."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"बुखार means?","options":["fever","cold","cough","pain"],"correctAnswer":"fever"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I have a fever and a headache too.","options":["मुझे बुखार है और सिर दर्द भी है।","मुझे बुखार है और पेट दर्द भी है।","मुझे सर्दी है और सिर दर्द भी है।","मुझे बुखार है और सिर दर्द नहीं है।"],"correctAnswer":"मुझे बुखार है और सिर दर्द भी है।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"मुझे मदद ___ ज़रूरत है।","options":["की","का","के","को"],"correctAnswer":"की"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He/she needs water.","wordBankItems":["उसे","पानी","की","ज़रूरत","है","।"],"correctAnswer":"उसे पानी की ज़रूरत है ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"अस्पताल means?","options":["hospital","pharmacy","clinic","doctor"],"correctAnswer":"hospital"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000016',1,'APPROVED','PUBLISHED',
'{"objectives":["Book and describe accommodation in Hindi at A1","Use मुझे X चाहिए for requests","Handle hotel check-in and check-out"],"explanation":{"intro":"Hotel and accommodation vocabulary covers checking in, room types, and basic requests in Hindi at A1.","culturalNote":"होटल और आवास — Hotel and Accommodation: होटल (hotel) = hotel (English loanword). कमरा (kamra) = room. बुकिंग (booking) = reservation. चेक इन/आउट (check in/out). मुझे X चाहिए (Mujhe X chahiye = I want/need X). धर्मशाला (dharamshala) = pilgrims'' rest house — traditional free or low-cost accommodation near religious sites. सराय (sarai) = caravanserai/inn — historical traveller''s rest. लॉज (lodge) = lodge (budget accommodation). Tourist hotels are graded 1-5 stars. Paying guest (PG) accommodation is common for students and workers in cities. Key: भारत में पर्यटन (Bharat mein paryatan = tourism in India) — Incredible India campaign. Heritage hotels (converting palaces/havelis — Rajasthan). Key phrase: क्या कमरा उपलब्ध है? (Kya kamra uplabdh hai? = Is a room available?). एक रात (ek raat = one night). चेकआउट कब है? (Checkout kab hai? = When is checkout?)."},"examples":[{"hindi":"मुझे एक कमरा चाहिए।","transliteration":"Mujhe ek kamra chahiye.","english":"I want/need one room."},{"hindi":"क्या नाश्ता शामिल है?","transliteration":"Kya nashta shaamil hai?","english":"Is breakfast included?"}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can handle hotel check-in and make basic requests in Hindi."}}',
'{"items":[{"word":"होटल","translation":"hotel","transliteration":"hotel","pronunciation":"ho-TEL","example":"होटल में रहना।"},{"word":"कमरा","translation":"room","transliteration":"kamra","pronunciation":"KAM-ra","example":"कमरा बुक करना।"},{"word":"चाहिए","translation":"want/need","transliteration":"chahiye","pronunciation":"cha-HI-ye","example":"मुझे चाहिए।"},{"word":"शामिल","translation":"included","transliteration":"shaamil","pronunciation":"SHAA-mil","example":"नाश्ता शामिल है।"},{"word":"उपलब्ध","translation":"available","transliteration":"uplabdh","pronunciation":"up-LAB-dh","example":"कमरा उपलब्ध है।"},{"word":"कब","translation":"when","transliteration":"kab","pronunciation":"kab","example":"कब है?"}]}',
'{"title":"मुझे X चाहिए — I want/need X (चाहिए = want/need, impersonal)","pattern":"मुझे X चाहिए = I want/need X. चाहिए (chahiye) = is wanted/needed (impersonal verb — does not conjugate for subject — always ''chahiye''). मुझे = to me (dative). X = the thing wanted (subject in Hindi — can be singular or plural). For plural: मुझे दो कमरे चाहिए (I need two rooms — chahiye stays the same even for plural X).","explanation":"चाहिए (chahiye) = want, need (impersonal — from चाहना = to want, but chahiye is a fixed form for ''is needed/wanted by'' — does not change for subject). Used with dative: मुझे (to me), आपको (to you formal), उसे (to him/her), हमें (to us). X चाहिए = X is needed. Contrast: चाहना (to want — conjugates normally: मैं चाहता हूँ = I want — habitual). चाहिए = immediate need/desire. चाहता हूँ = ongoing want/desire.","examples":[{"sentence":"आपको क्या चाहिए?","transliteration":"Aapko kya chahiye?","translation":"What do you need?"},{"sentence":"हमें दो टिकट चाहिए।","transliteration":"Hamein do ticket chahiye.","translation":"We need two tickets."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"चाहिए means?","options":["want/need","like","have","give"],"correctAnswer":"want/need"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I want/need one room.","options":["मुझे एक कमरा चाहिए।","मुझे दो कमरे चाहिए।","आपको एक कमरा चाहिए।","मुझे एक कमरा पसंद है।"],"correctAnswer":"मुझे एक कमरा चाहिए।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"हमें दो टिकट ___ ।","options":["चाहिए","है","हैं","होते"],"correctAnswer":"चाहिए"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: What do you need?","wordBankItems":["आपको","क्या","चाहिए","?"],"correctAnswer":"आपको क्या चाहिए ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"उपलब्ध means?","options":["available","included","occupied","reserved"],"correctAnswer":"available"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000017',1,'APPROVED','PUBLISHED',
'{"objectives":["Ask for and give directions in Hindi at A1","Use दाईं/बाईं तरफ़ for right/left","Navigate simple routes using postpositions"],"explanation":{"intro":"Directions vocabulary covers asking and giving directions, left/right/straight, and landmark-based navigation in Hindi at A1.","culturalNote":"दिशाएँ और रास्ता — Directions: दिशा (disha) = direction (Sanskrit). रास्ता (raasta) = road/way/route. सीधे जाइए (seedhe jaiye = go straight). दाईं तरफ़ (dayin taraf = to the right). बाईं तरफ़ (baayin taraf = to the left). पास में (paas mein = nearby). दूर (door = far). मुड़ना (mudna = to turn). कितनी दूर है? (Kitni door hai? = How far is it?). The four cardinal directions: उत्तर (uttar = north), दक्षिण (dakshin = south), पूर्व (poorva = east), पश्चिम (pashchim = west) — important for Vastu Shastra (Hindu architectural directional system). Street addresses in India often use landmarks rather than house numbers: ''Bank के पास'' (near the bank), ''मंदिर के सामने'' (in front of the temple). Auto-rickshaw/taxi navigation: most effective to name a landmark or area. Cultural: Asking directions from strangers is completely normal — people are generally helpful. Pointing directions with hand gestures is common."},"examples":[{"hindi":"बाज़ार कहाँ है? सीधे जाइए, फिर दाईं तरफ़ मुड़िए।","transliteration":"Baazaar kahaan hai? Seedhe jaiye, phir dayin taraf mudiye.","english":"Where is the market? Go straight, then turn right."},{"hindi":"स्टेशन यहाँ से कितनी दूर है?","transliteration":"Station yahaan se kitni door hai?","english":"How far is the station from here?"}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can ask for and give basic directions in Hindi."}}',
'{"items":[{"word":"सीधे","translation":"straight","transliteration":"seedhe","pronunciation":"SEED-he","example":"सीधे जाइए।"},{"word":"दाईं तरफ़","translation":"to the right","transliteration":"dayin taraf","pronunciation":"daa-YIN ta-RAF","example":"दाईं तरफ़ मुड़िए।"},{"word":"बाईं तरफ़","translation":"to the left","transliteration":"baayin taraf","pronunciation":"baa-YIN ta-RAF","example":"बाईं तरफ़ जाइए।"},{"word":"पास में","translation":"nearby","transliteration":"paas mein","pronunciation":"paas mein","example":"पास में है।"},{"word":"दूर","translation":"far","transliteration":"door","pronunciation":"door","example":"बहुत दूर है।"},{"word":"मुड़िए","translation":"turn (polite imperative)","transliteration":"mudiye","pronunciation":"MU-di-ye","example":"यहाँ मुड़िए।"}]}',
'{"title":"Verb stem + इए — polite imperative (जाइए, मुड़िए, लीजिए)","pattern":"Verb stem + इए = polite imperative (आप-form command). Used for giving polite instructions/directions. जाना (to go) → जाइए (please go). मुड़ना (to turn) → मुड़िए (please turn). लेना (to take) → लीजिए (please take). For informal: जाओ, मुड़ो, लो. For very informal: जा, मुड़, ले.","explanation":"Hindi imperatives: (1) Polite (आप-form): stem + इए — most respectful, used with strangers/elders. (2) Informal (तुम-form): stem + ओ — friends/younger. (3) Very informal (तू-form): stem alone — close family/intimates. For directions to strangers: always use polite -इए form. Key direction imperatives: जाइए (please go), मुड़िए (please turn), रुकिए (please stop), आइए (please come), देखिए (please look). Negative polite: मत + verb — मत जाइए (please don''t go).","examples":[{"sentence":"यहाँ बाईं तरफ़ मुड़िए।","transliteration":"Yahaan baayin taraf mudiye.","translation":"Please turn left here."},{"sentence":"आगे जाइए और दाईं तरफ़ मुड़िए।","transliteration":"Aage jaiye aur dayin taraf mudiye.","translation":"Please go forward and turn right."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"सीधे means?","options":["straight","right","left","forward"],"correctAnswer":"straight"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Where is the market? Go straight, then turn right.","options":["बाज़ार कहाँ है? सीधे जाइए, फिर दाईं तरफ़ मुड़िए।","बाज़ार कहाँ है? सीधे जाइए, फिर बाईं तरफ़ मुड़िए।","दुकान कहाँ है? सीधे जाइए, फिर दाईं तरफ़ मुड़िए।","बाज़ार कहाँ है? दाईं तरफ़ जाइए, फिर सीधे मुड़िए।"],"correctAnswer":"बाज़ार कहाँ है? सीधे जाइए, फिर दाईं तरफ़ मुड़िए।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"यहाँ बाईं तरफ़ ___ ।","options":["मुड़िए","जाइए","रुकिए","देखिए"],"correctAnswer":"मुड़िए"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Please go forward and turn right.","wordBankItems":["आगे","जाइए","और","दाईं","तरफ़","मुड़िए","।"],"correctAnswer":"आगे जाइए और दाईं तरफ़ मुड़िए ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"दूर means?","options":["far","near","close","here"],"correctAnswer":"far"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000018',1,'APPROVED','PUBLISHED',
'{"objectives":["Express emotions and feelings in Hindi at A1","Use मैं X हूँ for emotional states","Ask about how someone is feeling"],"explanation":{"intro":"Emotions vocabulary covers basic feelings and how to express and ask about emotional states in Hindi at A1.","culturalNote":"भावनाएँ — Emotions: भावना (bhaavna) = feeling/emotion (Sanskrit). खुश (khush) = happy (Persian/Urdu origin — same root as English ''josh''). दुखी (dukhi) = sad. थका हुआ (thaka hua = tired — past participle form). डरा हुआ (dara hua = scared). गुस्सा (gussa) = angry (also used as noun: मुझे गुस्सा आया = I got angry). हैरान (hairan) = surprised. शर्मिंदा (sharminda) = embarrassed (sharm = shame). Cultural: भारतीय संस्कृति में भावनाओं की अभिव्यक्ति (emotional expression in Indian culture) varies significantly by context — public emotional restraint is common in formal settings, but family/social contexts can be highly expressive. Bollywood has famously exaggerated emotional expression. Rasa (रस) — the 9 aesthetic emotions of classical Indian arts (navarasa). Karuna (करुणा = compassion) is considered the highest emotion in Buddhist/Hindu philosophy. ''चेहरे पर मुस्कान'' (chehre par muskaan = smile on the face) is a common compliment."},"examples":[{"hindi":"मैं आज बहुत खुश हूँ।","transliteration":"Main aaj bahut khush hoon.","english":"I am very happy today."},{"hindi":"वह थका हुआ दिख रहा है।","transliteration":"Vah thaka hua dikh raha hai.","english":"He is looking tired."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can express basic emotions and feelings in Hindi."}}',
'{"items":[{"word":"खुश","translation":"happy","transliteration":"khush","pronunciation":"khush","example":"बहुत खुश हूँ।"},{"word":"दुखी","translation":"sad","transliteration":"dukhi","pronunciation":"du-KHEE","example":"दुखी होना।"},{"word":"थका हुआ","translation":"tired","transliteration":"thaka hua","pronunciation":"THA-ka HU-a","example":"थका हुआ हूँ।"},{"word":"गुस्सा","translation":"angry","transliteration":"gussa","pronunciation":"GUS-sa","example":"गुस्सा आना।"},{"word":"हैरान","translation":"surprised","transliteration":"hairan","pronunciation":"hai-RAAN","example":"हैरान हूँ।"},{"word":"दिखना","translation":"to appear/look","transliteration":"dikhna","pronunciation":"DIKH-na","example":"थका दिख रहा है।"}]}',
'{"title":"X दिख रहा/रही है — X is looking/appearing (दिखना in continuous)","pattern":"Subject + adjective/state + दिख रहा/रही/रहे है/हैं = Subject is looking/appearing [adjective]. दिखना = to appear, look (intransitive). Continuous: दिख रहा है (masc. sg.), दिख रही है (fem. sg.), दिख रहे हैं (masc. pl./formal). X थका हुआ दिख रहा है = X is looking tired.","explanation":"दिखना (dikhna) = to appear, to be seen, to look (intransitive — no object). Continuous dikh raha/rahi hai = is looking/appearing. Adjective before दिख: describes how the subject appears. थका हुआ (thaka hua) = tired (participle phrase — past participle of थकना = to tire + हुआ = having). दिखना vs. देखना: दिखना = to appear/be seen (intransitive). देखना = to see/look at (transitive — requires object).","examples":[{"sentence":"वह आज खुश दिख रही है।","transliteration":"Vah aaj khush dikh rahi hai.","translation":"She is looking happy today."},{"sentence":"बच्चे थके हुए दिख रहे हैं।","transliteration":"Bachche thake hue dikh rahe hain.","translation":"The children are looking tired."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"खुश means?","options":["happy","sad","angry","afraid"],"correctAnswer":"happy"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I am very happy today.","options":["मैं आज बहुत खुश हूँ।","मैं कल बहुत खुश हूँ।","मैं आज बहुत दुखी हूँ।","हम आज बहुत खुश हैं।"],"correctAnswer":"मैं आज बहुत खुश हूँ।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"वह आज खुश दिख ___ है।","options":["रही","रहा","रहे","रही हैं"],"correctAnswer":"रही"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The children are looking tired.","wordBankItems":["बच्चे","थके","हुए","दिख","रहे","हैं","।"],"correctAnswer":"बच्चे थके हुए दिख रहे हैं ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"हैरान means?","options":["surprised","confused","worried","curious"],"correctAnswer":"surprised"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000019',1,'APPROVED','PUBLISHED',
'{"objectives":["Name sports and games in Hindi at A1","Use X खेलना to talk about playing sports","Talk about favourite sports"],"explanation":{"intro":"Sports vocabulary covers popular Indian and international sports, how to say you play them, and expressing favourite sports in Hindi at A1.","culturalNote":"खेल-कूद — Sports and Games: खेल (khel) = game/sport. क्रिकेट (cricket) — India''s most popular sport — national obsession. हॉकी (hockey) = field hockey — India''s national sport (though cricket is more popular). कबड्डी (kabaddi) = traditional contact sport — national game promoted by Pro Kabaddi League. शतरंज (shatranj) = chess — invented in India (chaturanga = 4 divisions of army). बैडमिंटन (badminton) = badminton. कुश्ती (kushti) = wrestling — ancient tradition. योग (yoga) = yoga. IPL (Indian Premier League) — world''s richest cricket league. Sachin Tendulkar (''God of Cricket''). खेलना (khelna) = to play (sports/games). मेरा पसंदीदा खेल X है (Mera pasandeeda khel X hai = My favourite sport is X). जीतना (jeetna) = to win. हारना (haarna) = to lose. प्रतियोगिता (pratiyogita) = competition."},"examples":[{"hindi":"मुझे क्रिकेट खेलना बहुत पसंद है।","transliteration":"Mujhe cricket khelna bahut pasand hai.","english":"I like playing cricket very much."},{"hindi":"मेरा पसंदीदा खेल शतरंज है।","transliteration":"Mera pasandeeda khel shatranj hai.","english":"My favourite game is chess."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can name sports in Hindi and talk about my favourite sport."}}',
'{"items":[{"word":"खेल","translation":"game/sport","transliteration":"khel","pronunciation":"khel","example":"खेल खेलना।"},{"word":"क्रिकेट","translation":"cricket","transliteration":"cricket","pronunciation":"kri-KET","example":"क्रिकेट खेलना।"},{"word":"कबड्डी","translation":"kabaddi","transliteration":"kabaddi","pronunciation":"ka-BAD-dee","example":"कबड्डी खेलना।"},{"word":"शतरंज","translation":"chess","transliteration":"shatranj","pronunciation":"SHA-tranj","example":"शतरंज खेलना।"},{"word":"जीतना","translation":"to win","transliteration":"jeetna","pronunciation":"JEET-na","example":"खेल जीतना।"},{"word":"पसंदीदा","translation":"favourite","transliteration":"pasandeeda","pronunciation":"pa-sand-EE-da","example":"पसंदीदा खेल।"}]}',
'{"title":"मेरा पसंदीदा X Y है — My favourite X is Y","pattern":"मेरा पसंदीदा X Y है = My favourite X is Y. पसंदीदा (pasandeeda) = favourite (from pasand + Persian -ida suffix). मेरा = my (masculine — agrees with X). पसंदीदा is invariant (does not change for gender). X = category (खेल, गाना, रंग etc.). Y = the specific favourite.","explanation":"पसंदीदा (pasandeeda) = favourite (adjective/compound from Persian — does not inflect for gender/number unlike native Hindi adjectives). मेरा/मेरी agrees with X (the category noun). मेरा पसंदीदा खेल = my favourite sport (खेल = masculine → मेरा). मेरी पसंदीदा किताब = my favourite book (किताब = feminine → मेरी). Y is the predicate noun (chess, cricket etc.).","examples":[{"sentence":"मेरा पसंदीदा रंग नीला है।","transliteration":"Mera pasandeeda rang neela hai.","translation":"My favourite colour is blue."},{"sentence":"उसकी पसंदीदा फ़िल्म कौन सी है?","transliteration":"Uski pasandeeda film kaun si hai?","translation":"What is his/her favourite film?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"शतरंज means?","options":["chess","cricket","kabaddi","hockey"],"correctAnswer":"chess"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"My favourite game is chess.","options":["मेरा पसंदीदा खेल शतरंज है।","मेरा पसंदीदा खेल क्रिकेट है।","मेरी पसंदीदा खेल शतरंज है।","मेरा पसंदीदा खेल शतरंज था।"],"correctAnswer":"मेरा पसंदीदा खेल शतरंज है।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"मेरा पसंदीदा रंग ___ है।","options":["नीला","नीली","नीले","नीलापन"],"correctAnswer":"नीला"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I like playing cricket very much.","wordBankItems":["मुझे","क्रिकेट","खेलना","बहुत","पसंद","है","।"],"correctAnswer":"मुझे क्रिकेट खेलना बहुत पसंद है ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"जीतना means?","options":["to win","to lose","to play","to compete"],"correctAnswer":"to win"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-00000000001a',1,'APPROVED','PUBLISHED',
'{"objectives":["Name major Indian festivals in Hindi at A1","Use X मनाना to talk about celebrating festivals","Describe what happens during a festival"],"explanation":{"intro":"Festival vocabulary covers major Hindu, Muslim, Sikh and national festivals and how to talk about celebrating them in Hindi at A1.","culturalNote":"त्योहार — Festivals: त्योहार (tyohaar) = festival. मनाना (manaana) = to celebrate. Key festivals: दीपावली/दिवाली (Deepawali/Diwali) = festival of lights — October/November — Lakshmi puja, diyas (clay lamps), fireworks. होली (Holi) = festival of colours — spring — Phalguna/March — throwing coloured powder. ईद (Eid) = Muslim festival — end of Ramadan. रक्षाबंधन (Rakshabandhan) = brother-sister festival — sisters tie rakhi on brothers'' wrists. दशहरा (Dussehra) = victory of good over evil — Rama''s victory over Ravana — burning of Ravana effigy. स्वतंत्रता दिवस (Swatantrata Diwas) = Independence Day — August 15. गणतंत्र दिवस (Gantantra Diwas) = Republic Day — January 26. Eid-ul-Fitr, Eid-ul-Adha. गुरुपर्व (Gurupurv) = Sikh festivals. क्रिसमस (Christmas) celebrated widely. Key: India''s religious diversity means festivals from many faiths are celebrated nationally."},"examples":[{"hindi":"हम दिवाली बहुत धूमधाम से मनाते हैं।","transliteration":"Hum Diwali bahut dhoomdhaam se manaate hain.","english":"We celebrate Diwali with great fanfare."},{"hindi":"होली में सब एक-दूसरे पर रंग डालते हैं।","transliteration":"Holi mein sab ek-doosre par rang daalte hain.","english":"At Holi everyone throws colours on each other."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can name major Indian festivals and describe how they are celebrated in Hindi."}}',
'{"items":[{"word":"त्योहार","translation":"festival","transliteration":"tyohaar","pronunciation":"tyo-HAAR","example":"त्योहार मनाना।"},{"word":"दिवाली","translation":"Diwali/festival of lights","transliteration":"Diwali","pronunciation":"di-WAA-lee","example":"दिवाली मनाना।"},{"word":"होली","translation":"Holi/festival of colours","transliteration":"Holi","pronunciation":"HO-lee","example":"होली खेलना।"},{"word":"मनाना","translation":"to celebrate","transliteration":"manaana","pronunciation":"ma-NAA-na","example":"त्योहार मनाना।"},{"word":"धूमधाम","translation":"fanfare/pomp","transliteration":"dhoomdhaam","pronunciation":"dhoom-DHAAM","example":"धूमधाम से।"},{"word":"रंग डालना","translation":"to throw colours","transliteration":"rang daalna","pronunciation":"rang DAAL-na","example":"रंग डालना।"}]}',
'{"title":"X में Y करते हैं — At/during X (festival) people do Y (में for festivals as time)","pattern":"Festival + में + activity + करते हैं = During festival people do activity. में = in/at/during (used for festivals as time periods). Habitual plural: करते हैं (they habitually do — masculine plural). Examples: दिवाली में दीप जलाते हैं (During Diwali they light lamps). होली में रंग डालते हैं (During Holi they throw colours).","explanation":"Festival time expression: X में = during X (festival). Habitual third person plural: verb stem + ते हैं. Used to describe what people generally do during a festival (habitual cultural truth). एक-दूसरे (ek-doosre) = each other (reciprocal pronoun — literally: one-other). पर = on (target of the action: रंग डालते हैं एक-दूसरे पर = throw colour on each other). सब (sab) = all/everyone.","examples":[{"sentence":"दिवाली में घर को दीयों से सजाते हैं।","transliteration":"Diwali mein ghar ko deeyon se sajaate hain.","translation":"During Diwali they decorate the house with lamps."},{"sentence":"ईद में मीठाई बाँटते हैं।","transliteration":"Eid mein mithai baante hain.","translation":"During Eid they distribute sweets."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"त्योहार means?","options":["festival","holiday","celebration","event"],"correctAnswer":"festival"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"We celebrate Diwali with great fanfare.","options":["हम दिवाली बहुत धूमधाम से मनाते हैं।","हम होली बहुत धूमधाम से मनाते हैं।","वे दिवाली बहुत धूमधाम से मनाते हैं।","हम दिवाली शांति से मनाते हैं।"],"correctAnswer":"हम दिवाली बहुत धूमधाम से मनाते हैं।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"दिवाली ___ घर को दीयों से सजाते हैं।","options":["में","पर","को","से"],"correctAnswer":"में"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: During Eid they distribute sweets.","wordBankItems":["ईद","में","मीठाई","बाँटते","हैं","।"],"correctAnswer":"ईद में मीठाई बाँटते हैं ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"मनाना means?","options":["to celebrate","to decorate","to distribute","to remember"],"correctAnswer":"to celebrate"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-00000000001b',1,'APPROVED','PUBLISHED',
'{"objectives":["Handle post office and bank interactions in Hindi at A1","Use मुझे X भेजना है for sending things","Conduct simple financial transactions"],"explanation":{"intro":"Post office and bank vocabulary covers mailing, sending money, and basic banking interactions in Hindi at A1.","culturalNote":"डाकघर और बैंक — Post Office and Bank: डाकघर (dakghar) = post office (dak = post/mail + ghar = house). चिट्ठी (chitthi) = letter. पार्सल (parcel) = parcel. टिकट (tikat) = stamp/ticket. भेजना (bhejna) = to send. पैसे (paise) = money. बैंक (bank) = bank. ATM = ATM. खाता (khaata) = account. चेक (check) = cheque. India Post is one of the world''s largest postal networks — 155,000 post offices. India Post Payments Bank (2018 — banking for rural India). UPI (Unified Payments Interface) — India''s revolutionary digital payment system — 50% of global real-time digital transactions. Paytm, PhonePe, Google Pay. Key: भारतीय रिज़र्व बैंक (Bharatiya Reserve Bank = Reserve Bank of India — central bank). Cash (नकद = nakad). रुपया — India''s currency — designed by Uday Kumar (₹ symbol 2010). India went from largely cash-based to 40% digital payments post-demonetisation (2016)."},"examples":[{"hindi":"मुझे यह चिट्ठी दिल्ली भेजनी है।","transliteration":"Mujhe yah chitthi Dilli bhejna hai.","english":"I need to send this letter to Delhi."},{"hindi":"बैंक में खाता खोलना है।","transliteration":"Bank mein khaata kholna hai.","english":"I need to open an account in the bank."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can handle basic post office and bank interactions in Hindi."}}',
'{"items":[{"word":"डाकघर","translation":"post office","transliteration":"dakghar","pronunciation":"DAK-ghar","example":"डाकघर जाना।"},{"word":"चिट्ठी","translation":"letter","transliteration":"chitthi","pronunciation":"CHIT-thi","example":"चिट्ठी भेजना।"},{"word":"भेजना","translation":"to send","transliteration":"bhejna","pronunciation":"BHEJ-na","example":"पार्सल भेजना।"},{"word":"खाता","translation":"account","transliteration":"khaata","pronunciation":"KHAA-ta","example":"बैंक खाता।"},{"word":"पैसे","translation":"money","transliteration":"paise","pronunciation":"PAI-se","example":"पैसे जमा करना।"},{"word":"खोलना","translation":"to open","transliteration":"kholna","pronunciation":"KHOL-na","example":"खाता खोलना।"}]}',
'{"title":"मुझे X करना है — I need to do X (obligation/intention with करना है)","pattern":"मुझे X करना है = I need to/have to do X. मुझे = to me (dative experiencer). X = verb infinitive (करना, जाना, भेजना etc.). है = is. Literally: ''to me doing X is'' — there is (a need) for me to do X. Used for: immediate obligation, intention, scheduled actions. Contrast: मुझे X करना चाहिए (I should do X — advisory/moral), मुझे X करना था (I had to do X — past), मुझे X करना होगा (I will have to do X — future).","explanation":"Obligation/intention: मुझे X करना है (dative + infinitive + है). The infinitive (करना, जाना, भेजना) is in the direct form before है. Gender agreement: the infinitive agrees with the object if it''s present. मुझे चिट्ठी भेजनी है (chitthi is feminine → भेजनी, feminine infinitive). मुझे पत्र भेजना है (patra = letter, masculine → भेजना). This gender agreement of the infinitive with the direct object is a key Hindi feature.","examples":[{"sentence":"मुझे कल जाना है।","transliteration":"Mujhe kal jaana hai.","translation":"I need to go tomorrow."},{"sentence":"उसे दवा लेनी है।","transliteration":"Use dawa leni hai.","translation":"He/she needs to take medicine."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"डाकघर means?","options":["post office","bank","shop","office"],"correctAnswer":"post office"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I need to send this letter to Delhi.","options":["मुझे यह चिट्ठी दिल्ली भेजनी है।","मुझे यह चिट्ठी मुंबई भेजनी है।","मुझे यह पार्सल दिल्ली भेजना है।","मुझे यह चिट्ठी दिल्ली भेजना है।"],"correctAnswer":"मुझे यह चिट्ठी दिल्ली भेजनी है।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"उसे दवा ___ है।","options":["लेनी","लेना","लेने","लेता"],"correctAnswer":"लेनी"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I need to go tomorrow.","wordBankItems":["मुझे","कल","जाना","है","।"],"correctAnswer":"मुझे कल जाना है ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"भेजना means?","options":["to send","to receive","to write","to open"],"correctAnswer":"to send"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-00000000001c',1,'APPROVED','PUBLISHED',
'{"objectives":["Use phone and internet vocabulary in Hindi at A1","Make and answer phone calls","Talk about internet activities"],"explanation":{"intro":"Phone and internet vocabulary covers making calls, texting, and common online activities in Hindi at A1.","culturalNote":"फ़ोन और इंटरनेट — Phone and Internet: फ़ोन (phone) = phone. मोबाइल (mobile) = mobile phone — universal in India. फ़ोन करना (phone karna = to make a call). बात करना (baat karna = to talk/converse). मैसेज भेजना (message bhejna = to send a message). इंटरनेट (internet). व्हाट्सएप (WhatsApp) — dominant messaging platform in India. यूट्यूब (YouTube) — very popular. OTT platforms: Netflix, Hotstar (now Disney+Hotstar), Amazon Prime. India has 800 million internet users (2nd largest in world). 5G rollout (2022-). Jio (Reliance Jio — disrupted telecom market 2016 — cheap data for all). Key: हैलो! (Hello! — phone greeting). आप से बात कर सकता/सकती हूँ? (Aap se baat kar sakta/sakti hoon? = Can I speak with you/May I talk?). कॉल बैक करना (call back karna = to call back). नेटवर्क (network). चार्ज करना (charge karna = to charge)."},"examples":[{"hindi":"मैं तुम्हें बाद में फ़ोन करूँगा।","transliteration":"Main tumhein baad mein phone karoonga.","english":"I will call you later."},{"hindi":"व्हाट्सएप पर मैसेज भेजो।","transliteration":"WhatsApp par message bhejo.","english":"Send a message on WhatsApp."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can use phone and internet vocabulary in Hindi and make simple calls."}}',
'{"items":[{"word":"फ़ोन करना","translation":"to make a call","transliteration":"phone karna","pronunciation":"phone KAR-na","example":"फ़ोन करना।"},{"word":"बात करना","translation":"to talk/converse","transliteration":"baat karna","pronunciation":"baat KAR-na","example":"बात करना।"},{"word":"मैसेज","translation":"message","transliteration":"message","pronunciation":"ME-sej","example":"मैसेज भेजना।"},{"word":"बाद में","translation":"later","transliteration":"baad mein","pronunciation":"baad mein","example":"बाद में मिलेंगे।"},{"word":"नेटवर्क","translation":"network","transliteration":"network","pronunciation":"NET-work","example":"नेटवर्क नहीं है।"},{"word":"चार्ज करना","translation":"to charge","transliteration":"charge karna","pronunciation":"charge KAR-na","example":"फ़ोन चार्ज करना।"}]}',
'{"title":"मैं X करूँगा/करूँगी — I will do X (future tense: करूँगा/करूँगी)","pattern":"मैं X करूँगा (male) / करूँगी (female) = I will do X. Future tense: verb stem + ऊँगा/ऊँगी/ऊँगे/एगी/एगा/एंगे. First person singular: करूँगा (male), करूँगी (female). जाऊँगा/जाऊँगी (I will go), आऊँगा/आऊँगी (I will come), फ़ोन करूँगा/करूँगी (I will call).","explanation":"Future tense in Hindi: stem + ऊँगा/ऊँगी (1st person singular), ओगे/ओगी (2nd person informal), एगा/एगी (3rd person singular), एँगे/एँगी (plural). Agreement: same as habitual (matches subject gender). करना → करूँगा (I male)/करूँगी (I female). जाना → जाऊँगा/जाऊँगी. बोलना → बोलूँगा/बोलूँगी. Irregular: होना → होगा/होगी (will be). Note: future tense is less commonly used in casual Hindi speech — present tense often substitutes for near future (कल आता हूँ = I''m coming tomorrow, lit. I come tomorrow).","examples":[{"sentence":"मैं कल आऊँगा।","transliteration":"Main kal aaooanga.","translation":"I will come tomorrow."},{"sentence":"वह परीक्षा में पास होगी।","transliteration":"Vah pariksha mein pass hogi.","translation":"She will pass the exam."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"बात करना means?","options":["to talk/converse","to listen","to write","to read"],"correctAnswer":"to talk/converse"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I will call you later.","options":["मैं तुम्हें बाद में फ़ोन करूँगा।","मैं तुम्हें अभी फ़ोन करूँगा।","मैं आपको बाद में फ़ोन करूँगा।","मैं तुम्हें बाद में मैसेज करूँगा।"],"correctAnswer":"मैं तुम्हें बाद में फ़ोन करूँगा।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"मैं कल ___ ।","options":["आऊँगा","आता हूँ","आ रहा हूँ","आया हूँ"],"correctAnswer":"आऊँगा"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: She will pass the exam.","wordBankItems":["वह","परीक्षा","में","पास","होगी","।"],"correctAnswer":"वह परीक्षा में पास होगी ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"बाद में means?","options":["later","before","now","then"],"correctAnswer":"later"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-00000000001d',1,'APPROVED','PUBLISHED',
'{"objectives":["Order food at a restaurant in Hindi at A1","Use मुझे X देना for ordering","Describe dishes and ask for the bill"],"explanation":{"intro":"Dining vocabulary covers ordering food, describing dishes, and paying the bill at a restaurant in Hindi at A1.","culturalNote":"भोजन और रेस्तराँ — Dining and Restaurants: रेस्तराँ (restaurant) = restaurant. खाना/भोजन (khaana/bhojan) = food/meal. मेन्यू (menu). वेटर (waiter). बिल (bill). मुझे X लाइए (Mujhe X laiye = Please bring me X — polite imperative of लाना = to bring). पानी (water). Key dishes: बिरयानी (biryani), दाल मखनी (dal makhani), पनीर (paneer = cottage cheese), नान (naan), समोसा (samosa), रसमलाई (rasmalai = sweet). मसालेदार (masaledar = spicy). मीठा (meetha = sweet). नमकीन (namkeen = salty). शाकाहारी/निरामिष (shakahari/niramish = vegetarian). माँसाहारी (maansahari = non-vegetarian). Cultural: restaurants often have separate menus or sections for veg/non-veg. South Indian (idli, dosa, sambar), North Indian (roti, sabzi), Chinese (Manchurian — Indian-Chinese fusion). Chai wallahs (tea stalls) are everywhere."},"examples":[{"hindi":"मुझे एक थाली और पानी दीजिए।","transliteration":"Mujhe ek thali aur paani dijiye.","english":"Please give me one thali and water."},{"hindi":"बिल लाइए, कृपया।","transliteration":"Bill laiye, kripaya.","english":"Please bring the bill."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can order food at a restaurant in Hindi and ask for the bill."}}',
'{"items":[{"word":"रेस्तराँ","translation":"restaurant","transliteration":"restaurant","pronunciation":"res-tuh-RAAN","example":"रेस्तराँ में खाना।"},{"word":"बिल","translation":"bill","transliteration":"bill","pronunciation":"bil","example":"बिल माँगना।"},{"word":"दीजिए","translation":"please give (polite imp.)","transliteration":"dijiye","pronunciation":"DEE-ji-ye","example":"पानी दीजिए।"},{"word":"लाइए","translation":"please bring (polite imp.)","transliteration":"laiye","pronunciation":"LA-i-ye","example":"खाना लाइए।"},{"word":"शाकाहारी","translation":"vegetarian","transliteration":"shakahari","pronunciation":"shaaka-HAA-ree","example":"शाकाहारी खाना।"},{"word":"कृपया","translation":"please","transliteration":"kripaya","pronunciation":"kri-PA-ya","example":"कृपया आइए।"}]}',
'{"title":"मुझे X दीजिए/लाइए — Please give/bring me X (polite imperative for ordering)","pattern":"मुझे X दीजिए = Please give me X. मुझे X लाइए = Please bring me X. दीजिए = polite imperative of देना (to give). लाइए = polite imperative of लाना (to bring). With indirect object (to whom): मुझे (to me — dative). The -इए form is polite/formal — suitable for restaurant/service contexts.","explanation":"देना (to give) → polite: दीजिए (please give). लाना (to bring) → polite: लाइए (please bring). Both take the dative-marked person (मुझे = to me) and direct object (X = what is given/brought). मुझे पानी दीजिए = Please give me water. क्या मुझे मेन्यू मिल सकता है? (Kya mujhe menu mil sakta hai? = Can I get the menu?). कृपया (kripaya) = please (polite addition — Sanskrit origin). बिल माँगना = to ask for the bill (माँगना = to ask for/demand).","examples":[{"sentence":"मुझे थोड़ा और चावल दीजिए।","transliteration":"Mujhe thoda aur chaawal dijiye.","translation":"Please give me a little more rice."},{"sentence":"कृपया नमक लाइए।","transliteration":"Kripaya namak laiye.","translation":"Please bring salt."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"कृपया means?","options":["please","thank you","excuse me","sorry"],"correctAnswer":"please"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Please give me one thali and water.","options":["मुझे एक थाली और पानी दीजिए।","मुझे दो थाली और पानी दीजिए।","मुझे एक थाली और चाय दीजिए।","आपको एक थाली और पानी दीजिए।"],"correctAnswer":"मुझे एक थाली और पानी दीजिए।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"कृपया नमक ___ ।","options":["लाइए","दीजिए","खाइए","पीजिए"],"correctAnswer":"लाइए"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Please give me a little more rice.","wordBankItems":["मुझे","थोड़ा","और","चावल","दीजिए","।"],"correctAnswer":"मुझे थोड़ा और चावल दीजिए ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"शाकाहारी means?","options":["vegetarian","non-vegetarian","spicy","sweet"],"correctAnswer":"vegetarian"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-00000000001e',1,'APPROVED','PUBLISHED',
'{"objectives":["Use descriptive adjectives in Hindi at A1","Practice adjective-noun agreement in gender and number","Build descriptive sentences"],"explanation":{"intro":"Descriptive adjectives vocabulary covers common size, quality and appearance adjectives and how they agree with nouns in Hindi at A1.","culturalNote":"विशेषण — Adjectives: विशेषण (visheshana) = adjective (Sanskrit). Key adjectives: बड़ा/बड़ी (bada/badi = big), छोटा/छोटी (chhota/chhoti = small), अच्छा/अच्छी (accha/acchi = good), बुरा/बुरी (bura/buri = bad), नया/नई (naya/nai = new), पुराना/पुरानी (purana/purani = old), लंबा/लंबी (lamba/lambi = tall/long), मोटा/मोटी (mota/moti = fat/thick), पतला/पतली (patla/patli = thin), सुंदर (sundar = beautiful — invariant), गर्म (garm = warm/hot — invariant), ठंडा/ठंडी (thanda/thandi = cold). Agreement rule: adjectives ending in -a/-ā inflect; invariant adjectives (ending in consonants or -ी) do not. एक अच्छा लड़का (ek accha ladka = a good boy — masc.). एक अच्छी लड़की (ek acchi ladki = a good girl — fem.). अच्छे लड़के (achche ladke = good boys — masc. pl.). Adjective placement: before noun (attributive) or after noun + copula (predicate)."},"examples":[{"hindi":"यह एक बड़ा और सुंदर शहर है।","transliteration":"Yah ek bada aur sundar shahar hai.","english":"This is a big and beautiful city."},{"hindi":"मेरी नई किताब बहुत अच्छी है।","transliteration":"Meri nai kitaab bahut acchi hai.","english":"My new book is very good."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can use descriptive adjectives in Hindi with correct gender agreement."}}',
'{"items":[{"word":"बड़ा/बड़ी","translation":"big (masc/fem)","transliteration":"bada/badi","pronunciation":"BA-da/BA-dee","example":"बड़ा घर।"},{"word":"छोटा/छोटी","translation":"small (masc/fem)","transliteration":"chhota/chhoti","pronunciation":"CHHO-ta/CHHO-tee","example":"छोटी बच्ची।"},{"word":"अच्छा/अच्छी","translation":"good (masc/fem)","transliteration":"accha/acchi","pronunciation":"ACH-cha/ACH-chi","example":"अच्छा खाना।"},{"word":"नया/नई","translation":"new (masc/fem)","transliteration":"naya/nai","pronunciation":"NA-ya/na-EE","example":"नया फ़ोन।"},{"word":"सुंदर","translation":"beautiful (invariant)","transliteration":"sundar","pronunciation":"SUN-dar","example":"सुंदर शहर।"},{"word":"पुराना/पुरानी","translation":"old (masc/fem)","transliteration":"purana/purani","pronunciation":"pu-RAA-na/pu-RAA-nee","example":"पुरानी किताब।"}]}',
'{"title":"Adjective agreement: -a → -ī before feminine nouns","pattern":"Inflecting adjectives (ending in -a/-ā): masculine form ends in -a; feminine form ends in -ī; masculine plural ends in -e. बड़ा (masc.) → बड़ी (fem.) → बड़े (masc. pl.). अच्छा → अच्छी → अच्छे. नया → नई → नए. Invariant adjectives (ending in consonant or -ī): सुंदर, गर्म, ठंडा (wait — ठंडा inflects: ठंडा → ठंडी → ठंडे).","explanation":"Adjective inflection in Hindi: (a) inflecting adjectives: end in -a (masc.), change to -ī (fem.) and -e (masc. pl./oblique). Examples: बड़ा/बड़ी/बड़े, अच्छा/अच्छी/अच्छे, नया/नई/नए. (b) invariant adjectives: do not change. Examples: सुंदर (sundar), गर्म (garm), साफ़ (saaf = clean), लाल (laal = red). Key test: if the masculine form ends in -a, it inflects. If it ends in a consonant, it doesn''t. Predicate position: लड़का बड़ा है (the boy is big — inflecting, masculine). Attributive: बड़ा लड़का (big boy — same as masculine predicate).","examples":[{"sentence":"यह पुरानी गाड़ी है।","transliteration":"Yah purani gaadi hai.","translation":"This is an old car."},{"sentence":"बड़े घर में रहना अच्छा लगता है।","transliteration":"Bade ghar mein rehna accha lagta hai.","translation":"Living in a big house feels good."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"सुंदर means?","options":["beautiful","good","nice","pretty"],"correctAnswer":"beautiful"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"My new book is very good.","options":["मेरी नई किताब बहुत अच्छी है।","मेरी पुरानी किताब बहुत अच्छी है।","मेरी नई किताब बहुत बड़ी है।","मेरा नया किताब बहुत अच्छा है।"],"correctAnswer":"मेरी नई किताब बहुत अच्छी है।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"यह ___ गाड़ी है।","options":["पुरानी","पुराना","पुराने","पुरानों"],"correctAnswer":"पुरानी"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: This is a big and beautiful city.","wordBankItems":["यह","एक","बड़ा","और","सुंदर","शहर","है","।"],"correctAnswer":"यह एक बड़ा और सुंदर शहर है ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"छोटी means?","options":["small (fem.)","big (fem.)","new (fem.)","old (fem.)"],"correctAnswer":"small (fem.)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

